/* =====================================================================
 * 76-work-decks-2.js — the rest of the ladder, as decks (the engine is
 * 65-work.js, the first eight careers 66-work-decks.js, the adult careers
 * 71-adult-work.js). This file: service, office, business, transport,
 * public service and the trades. 77-work-decks-3.js carries health, tech,
 * science, law, education, media and the entertainment careers.
 *
 * A career here is a meter, six or seven cards, and a place in the web:
 *   - a few UNIVERSAL cards (UNI below) any job can deal, written once with {{team}}, {{boss}} and {{Boss}}
 *     filled in for the job's category (and a job can override them)
 *   - three or four cards that are only this job's
 * The shortcut ways carry a price (W's last slot, `eff`), so the honest road is never the bad deal; see 66-work-decks.js.
 * K(id, name, emoji, text, ways, ok, meh, bad, extras): a one-decision card; give `stages` in extras for more.
 * ===================================================================== */

const K = (id, name, emoji, text, ways, ok, meh, bad, o) => Object.assign({ id, name, emoji, base: 0.5, stages: [{ text, ways }], ok, meh, bad }, o || {});
const MW = {
  standing: WORDS('On thin ice', 'Replaceable', 'Reliable', 'Valued', 'Indispensable'),
  craft: WORDS('Sloppy', 'Learning', 'Competent', 'Respected', 'A master'),
  trust: WORDS('Doubted', 'Watched', 'Trusted', 'Relied on', 'The one they ask for'),
  pull: WORDS('Sidelined', 'Noticed', 'Connected', 'Influential', 'A power in the room'),
  name: WORDS('Unknown', 'Emerging', 'Established', 'Admired', 'Iconic'),
  class: WORDS('Struggling', 'Finding your feet', 'Steady', 'Respected', 'Remembered'),
};
const TPL_CAT = {
  service: { team: 'the crew', boss: 'your manager', Boss: 'Your manager' }, office: { team: 'the team', boss: 'your manager', Boss: 'Your manager' },
  business: { team: 'the office', boss: 'your director', Boss: 'Your director' }, transport: { team: 'the crew', boss: 'dispatch', Boss: 'Dispatch' },
  public: { team: 'the shift', boss: 'your supervisor', Boss: 'Your supervisor' }, trades: { team: 'the crew', boss: 'the foreman', Boss: 'The foreman' },
  health: { team: 'the unit', boss: 'the director', Boss: 'The director' }, tech: { team: 'the team', boss: 'your lead', Boss: 'Your lead' },
  science: { team: 'the lab', boss: 'the PI', Boss: 'The PI' }, law: { team: 'the firm', boss: 'the partner', Boss: 'The partner' },
  education: { team: 'the staff', boss: 'the principal', Boss: 'The principal' }, media: { team: 'the studio', boss: 'your editor', Boss: 'Your editor' },
  fame: { team: 'the production', boss: 'your agent', Boss: 'Your agent' },
};
function tpl(v, m) {
  if (typeof v === 'string') return v.replace(/\{\{(\w+)\}\}/g, (x, k) => (m[k] === undefined ? '' : m[k]));
  if (Array.isArray(v)) return v.map((x) => tpl(x, m));
  if (v && typeof v === 'object') { const o = {}; for (const k in v) o[k] = tpl(v[k], m); return o; }
  return v;
}
